local project=require("setup.project")local Session=require("setup.session")local Server=require("setup.server")local M={}M.USAGE="Usage: braincloud-setup [<projectDir>] [--out <path>] [--refresh] [--server <url>] [--no-browser] [--timeout <minutes>]"function M.parse(args)local opts={browser=true,timeout=30}local i=1 while args[i]do local a=args[i]if a=="--out"then opts.out=args[i+1]i=i+1 elseif a=="--server"then opts.server=args[i+1]i=i+1 elseif a=="--refresh"then opts.refresh=true elseif a=="--no-browser"then opts.browser=false elseif a=="--timeout"then opts.timeout=tonumber(args[i+1])or 30 i=i+1 elseif a=="-h"or a=="--help"then opts.help=true elseif a:sub(1,1)=="-"then opts.bad=a else opts.projectDir=a end i=i+1 end return opts end function M.openBrowser(url)if love and love.system and love.system.openURL then return love.system.openURL(url)end local sep=package.config:sub(1,1)if sep=="\\"then return os.execute('start "" "'..url..'"')~=nil end local opener=(io.popen("uname"):read("*l")=="Darwin")and"open"or"xdg-open"return os.execute(opener.." '"..url.."' >/dev/null 2>&1 &")~=nil end function M.start(opts,readAsset,log)log=log or print local output=opts.out or project.defaultOutput(opts.projectDir or".")local session=Session.new(output,{serverUrl=opts.server})local runner={output=output,session=session}if opts.refresh then session:refreshConfig()log("Refreshed "..output)runner.finished=true function runner.poll()return true end return runner end local server=Server.new(session,{readAsset=readAsset})server:start()runner.server=server runner.deadline=os.time()+opts.timeout*60 log("brainCloud setup is open at "..server:url())log("Writing config to "..output)if not opts.browser or not M.openBrowser(server:url())then log("Open that address in your browser to continue.")end function runner.url()return server:url()end function runner.poll()if runner.finished then return true end local done=server:poll()if done or os.time()>runner.deadline then if not done then log("brainCloud setup timed out after "..opts.timeout.." minutes.")end server:stop()runner.finished=true if project.read(output)then log("Done. In your game:\n  local bc = require(\"braincloud\").new()\n  bc:init()")end end return runner.finished end return runner end return M
